use std::io::{self, BufRead, Write};

struct Node {
    key: i64,
    l: Option<Box<Node>>,
    r: Option<Box<Node>>,
}

fn insert(root: &mut Option<Box<Node>>, x: i64) -> bool {
    let mut cur = root;
    while let Some(n) = cur {
        if x == n.key {
            return false;
        }
        cur = if x < n.key { &mut n.l } else { &mut n.r };
    }
    *cur = Some(Box::new(Node { key: x, l: None, r: None }));
    true
}

fn contains(root: &Option<Box<Node>>, x: i64) -> bool {
    let mut cur = root;
    while let Some(n) = cur {
        if x == n.key {
            return true;
        }
        cur = if x < n.key { &n.l } else { &n.r };
    }
    false
}

fn delete(root: &mut Option<Box<Node>>, x: i64) -> bool {
    let mut cur = root;
    loop {
        match cur {
            None => return false,
            Some(n) if x < n.key => cur = &mut cur.as_mut().unwrap().l,
            Some(n) if x > n.key => cur = &mut cur.as_mut().unwrap().r,
            Some(_) => break,
        }
    }
    let mut node = cur.take().unwrap();
    *cur = match (node.l.take(), node.r.take()) {
        (None, None) => None,
        (Some(l), None) => Some(l),
        (None, Some(r)) => Some(r),
        (Some(l), Some(r)) => {
            let mut right = Some(r);
            let succ = take_min(&mut right);
            let mut s = succ;
            s.l = Some(l);
            s.r = right;
            Some(s)
        }
    };
    true
}

fn take_min(root: &mut Option<Box<Node>>) -> Box<Node> {
    let mut cur = root;
    while cur.as_ref().unwrap().l.is_some() {
        cur = &mut cur.as_mut().unwrap().l;
    }
    let mut n = cur.take().unwrap();
    *cur = n.r.take();
    n
}

fn run() {
    let stdin = io::stdin();
    let mut out = String::new();
    let mut root: Option<Box<Node>> = None;
    for line in stdin.lock().lines() {
        let line = line.unwrap();
        let mut it = line.split_whitespace();
        let cmd = match it.next() {
            Some(c) => c,
            None => continue,
        };
        let arg: Option<i64> = it.next().and_then(|s| s.parse().ok());
        match cmd {
            "insert" => out.push_str(if insert(&mut root, arg.unwrap()) { "ok\n" } else { "dup\n" }),
            "contains" => out.push_str(if contains(&root, arg.unwrap()) { "yes\n" } else { "no\n" }),
            "delete" => out.push_str(if delete(&mut root, arg.unwrap()) { "ok\n" } else { "missing\n" }),
            "inorder" => {
                let mut v = Vec::new();
                let mut stack: Vec<&Node> = Vec::new();
                let mut cur = root.as_deref();
                while cur.is_some() || !stack.is_empty() {
                    while let Some(n) = cur {
                        stack.push(n);
                        cur = n.l.as_deref();
                    }
                    let n = stack.pop().unwrap();
                    v.push(n.key.to_string());
                    cur = n.r.as_deref();
                }
                if v.is_empty() {
                    out.push_str("<empty>\n");
                } else {
                    out.push_str(&v.join(" "));
                    out.push('\n');
                }
            }
            "height" => {
                let mut h = 0;
                let mut level: Vec<&Node> = root.as_deref().into_iter().collect();
                while !level.is_empty() {
                    h += 1;
                    let mut next = Vec::new();
                    for n in level {
                        if let Some(c) = n.l.as_deref() {
                            next.push(c);
                        }
                        if let Some(c) = n.r.as_deref() {
                            next.push(c);
                        }
                    }
                    level = next;
                }
                out.push_str(&format!("{}\n", h));
            }
            "min" | "max" => {
                let mut cur = root.as_deref();
                let mut res = None;
                while let Some(n) = cur {
                    res = Some(n.key);
                    cur = if cmd == "min" { n.l.as_deref() } else { n.r.as_deref() };
                }
                match res {
                    Some(k) => out.push_str(&format!("{}\n", k)),
                    None => out.push_str("empty\n"),
                }
            }
            _ => {}
        }
    }
    io::stdout().write_all(out.as_bytes()).unwrap();
    // avoid recursive drop on deep trees
    std::mem::forget(root);
}

fn main() {
    let h = std::thread::Builder::new().stack_size(256 << 20).spawn(run).unwrap();
    h.join().unwrap();
}

